const workerCapabilities = `-- name: WorkerCapabilities :many
SELECT worker_id, paradigm_key, paradigm_version
FROM misko.worker_capabilities
WHERE worker_id = $1
ORDER BY paradigm_key, paradigm_version
`

func (q *Queries) WorkerCapabilities(ctx context.Context, workerID string) ([]MiskoWorkerCapability, error) {
	rows, err := q.db.Query(ctx, workerCapabilities, workerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []MiskoWorkerCapability
	for rows.Next() {
		var i MiskoWorkerCapability
		if err := rows.Scan(&i.WorkerID, &i.ParadigmKey, &i.ParadigmVersion); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
